#include <cassert>
#include <cstring>

#include "vertex/std/format.hpp"
#include "vertex/std/io.hpp"

using namespace vx;

// 0.000000000000000000000000000000000000000000001401298464324817070923729583289916131280261941876515771757068283889791082685860601486638188362121582031250
// 0.

int main()
{
    const double x = DBL_TRUE_MIN;

    string s;
    s.resize(5000);

    strconv::float_to_string_format_options fmt;
    fmt.precision = 4096;
    const auto res = strconv::write_float_fixed(x, s.data(), s.size(), fmt);
    io::print_raw(s.data(), s.size());

    return 0;
}
